import mqtt from 'mqtt'
const brokers = [
  ['hivemq', 'wss://broker.hivemq.com:8884/mqtt'],
  ['emqx', 'wss://broker.emqx.io:8084/mqtt'],
  ['mosquitto', 'wss://test.mosquitto.org:8081/mqtt'],
]
const topic = 'korlabirent/test/' + Date.now()
for (const [name, url] of brokers) {
  await new Promise((resolve) => {
    const c = mqtt.connect(url, { connectTimeout: 8000, reconnectPeriod: 0, clientId: 'kl-test-'+Math.random().toString(16).slice(2) })
    let done = false
    const finish = (msg) => { if (done) return; done = true; console.log(name, msg); try { c.end(true) } catch {}; resolve() }
    const t = setTimeout(() => finish('TIMEOUT'), 15000)
    c.on('connect', () => {
      console.log(name, 'connected')
      c.publish(topic, JSON.stringify({name, score: 42}), { qos: 0, retain: true }, (err) => {
        if (err) return finish('publish error ' + err.message)
        setTimeout(() => {
          const sub = mqtt.connect(url, { connectTimeout: 8000, reconnectPeriod: 0, clientId: 'kl-sub-'+Math.random().toString(16).slice(2) })
          sub.on('message', (tp, payload) => { console.log(name, 'got', tp, payload.toString()); sub.end(true); finish('OK') })
          sub.on('connect', () => sub.subscribe(topic, { qos: 0 }))
          sub.on('error', e => { console.log(name, 'sub err', e.message); sub.end(true); finish('SUBERR') })
          setTimeout(() => { sub.end(true); finish('NO RETAINED') }, 5000)
        }, 500)
      })
    })
    c.on('error', e => { console.log(name, 'err', e.message); finish('ERR') })
    c.on('close', () => {})
    setTimeout(() => { if (!done) { c.end(true); finish('CONNECT TIMEOUT') } }, 10000)
  })
}
