export function computeLevelScore(level, state, {undoCount=0}={}) {
  const embers = level.emberCells.length;
  const base = 300;
  const emberPts = embers*75;
  const par = level.par;
  const efficiency = Math.max(0, par - state.moves) * 30;
  const onPar = state.moves <= par ? 200 : 0;
  const chain = state.maxChain * 40;
  const perfect = state.moves === level.optimal ? 150 : 0;
  const penalty = undoCount * 20;
  return { total: Math.max(0, base+emberPts+efficiency+onPar+chain+perfect-penalty), base, emberPts, efficiency, onPar, chain, perfect, penalty };
}
