/**
 * Kor Labirenti — deterministic turn rules.
 *
 * The same module powers the browser game and the level validator in Node.
 * Everything here is pure: a state is a small plain object and step() returns
 * a new state instead of mutating the input.
 */

export const WALL = '#'
export const FLOOR = '.'
export const EMBER = '*'
export const EXIT = 'E'
export const START = 'S'
export const ICE = 'I'
export const PORTAL_A = 'P'
export const PORTAL_B = 'Q'
export const CRACKED = '~'
export const FLAME = '^'
export const KEY = 'K'
export const GATE = 'G'
export const VOID = 'V'

export const DIRS = {
  up: [-1, 0],
  right: [0, 1],
  down: [1, 0],
  left: [0, -1],
}

export const ACTION_LABELS = {
  up: 'yukarı',
  right: 'sağ',
  down: 'aşağı',
  left: 'sol',
  wait: 'bekle',
}

const PORTALS = new Set([PORTAL_A, PORTAL_B])
const BLOCKING = new Set([WALL, VOID])

function lcm(a, b) {
  if (!a || !b) return 1
  let x = a
  let y = b
  while (y) {
    const t = x % y
    x = y
    y = t
  }
  return (a * b) / x
}

export function hashString(value) {
  let h = 2166136261 >>> 0
  const text = String(value)
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

export function mulberry32(seed) {
  let a = seed >>> 0
  return function random() {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/**
 * Convert an ASCII level definition into the metadata used by the rules.
 * rows are strings; sentries are {path:[[row,col],...], mode:'loop'|'pingpong'}.
 */
export function parseLevel(def) {
  if (!def || !Array.isArray(def.rows) || def.rows.length < 3) {
    throw new Error('Level needs at least three rows')
  }
  const rows = def.rows.map((row) => String(row))
  const height = rows.length
  const width = rows[0].length
  if (!width || rows.some((row) => row.length !== width)) {
    throw new Error(`Level ${def.id || '(unnamed)'} is not rectangular`)
  }

  const emberCells = []
  const emberIndex = new Map()
  const crackedCells = []
  const crackedIndex = new Map()
  const flameCells = []
  const keyCells = []
  const gateCells = []
  const portalCells = []
  let start = -1
  let exit = -1

  for (let r = 0; r < height; r++) {
    for (let c = 0; c < width; c++) {
      const ch = rows[r][c]
      const idx = r * width + c
      if (ch === START) {
        if (start >= 0) throw new Error('Level has more than one start')
        start = idx
      } else if (ch === EXIT) {
        if (exit >= 0) throw new Error('Level has more than one exit')
        exit = idx
      } else if (ch === EMBER) {
        emberIndex.set(idx, emberCells.length)
        emberCells.push(idx)
      } else if (ch === CRACKED) {
        crackedIndex.set(idx, crackedCells.length)
        crackedCells.push(idx)
      } else if (ch === FLAME) {
        flameCells.push(idx)
      } else if (ch === KEY) {
        keyCells.push(idx)
      } else if (ch === GATE) {
        gateCells.push(idx)
      } else if (PORTALS.has(ch)) {
        portalCells.push(idx)
      }
    }
  }

  if (start < 0) throw new Error('Level has no start')
  if (exit < 0) throw new Error('Level has no exit')
  if (portalCells.length !== 0 && portalCells.length !== 2) {
    throw new Error('Level needs zero or exactly two portal tiles')
  }

  let period = 1
  if (flameCells.length) period = lcm(period, 2)

  const sentries = (def.sentries || []).map((sentry, index) => {
    if (!Array.isArray(sentry.path) || sentry.path.length < 2) {
      throw new Error(`Sentry ${index} needs a path of at least two cells`)
    }
    const path = sentry.path.map(([r, c]) => {
      if (r < 0 || c < 0 || r >= height || c >= width) {
        throw new Error(`Sentry ${index} leaves the board`)
      }
      const ch = rows[r][c]
      if (ch === WALL || ch === VOID) {
        throw new Error(`Sentry ${index} walks through a wall`)
      }
      return r * width + c
    })
    const mode = sentry.mode === 'loop' ? 'loop' : 'pingpong'
    const length = mode === 'loop' ? path.length : 2 * (path.length - 1)
    period = lcm(period, length)
    return {
      path,
      mode,
      startIndex: Math.max(0, Math.min(path.length - 1, Number(sentry.startIndex) || 0)),
    }
  })

  const level = {
    ...def,
    rows,
    width,
    height,
    start,
    exit,
    emberCells,
    emberIndex,
    crackedCells,
    crackedIndex,
    flameCells,
    keyCells,
    gateCells,
    portalCells,
    portalMap: portalCells.length === 2 ? new Map([[portalCells[0], portalCells[1]], [portalCells[1], portalCells[0]]]) : new Map(),
    sentries,
    period,
    flamePhase: Number(def.flamePhase) || 0,
    par: Number(def.par) || 0,
    optimal: Number(def.optimal) || 0,
  }
  return level
}

export function cellChar(level, index) {
  if (!Number.isInteger(index) || index < 0 || index >= level.width * level.height) return WALL
  return level.rows[Math.floor(index / level.width)][index % level.width]
}

export function createState(level) {
  return {
    pos: level.start,
    embers: 0,
    key: false,
    crumbled: 0,
    turn: 0,
    moves: 0,
    chain: 0,
    maxChain: 0,
    status: 'playing',
    deathReason: '',
  }
}

export function cloneState(state) {
  return {
    pos: state.pos,
    embers: state.embers,
    key: state.key,
    crumbled: state.crumbled,
    turn: state.turn,
    moves: state.moves,
    chain: state.chain,
    maxChain: state.maxChain,
    status: state.status,
    deathReason: state.deathReason || '',
  }
}

export function isFlameActive(level, state) {
  if (!level.flameCells.length) return false
  return (state.turn + level.flamePhase) % 2 === 0
}

export function sentryPosition(sentry, turn) {
  const length = sentry.path.length
  if (sentry.mode === 'loop') {
    return sentry.path[(sentry.startIndex + turn) % length]
  }
  const period = 2 * (length - 1)
  const t = (sentry.startIndex + turn) % period
  const i = t < length ? t : period - t
  return sentry.path[i]
}

export function sentryAt(level, state, index) {
  for (const sentry of level.sentries) {
    if (sentryPosition(sentry, state.turn) === index) return sentry
  }
  return null
}

export function isBlocked(level, state, index, { ignoreSentries = false } = {}) {
  if (!Number.isInteger(index) || index < 0 || index >= level.width * level.height) return true
  const ch = cellChar(level, index)
  if (BLOCKING.has(ch)) return true
  if (ch === GATE && !state.key) return true
  if (ch === FLAME && isFlameActive(level, state)) return true
  const cracked = level.crackedIndex.get(index)
  if (cracked !== undefined && (state.crumbled & (1 << cracked))) return true
  if (!ignoreSentries && sentryAt(level, state, index)) return true
  return false
}

function collectAt(level, state, index, collected) {
  const ember = level.emberIndex.get(index)
  if (ember === undefined) return false
  const bit = 1 << ember
  if (state.embers & bit) return false
  state.embers |= bit
  collected.push(index)
  return true
}

function crumbleAt(level, state, index) {
  const cracked = level.crackedIndex.get(index)
  if (cracked === undefined) return false
  const bit = 1 << cracked
  if (state.crumbled & bit) return false
  state.crumbled |= bit
  return true
}

function advanceTurn(level, state) {
  state.turn += 1
  state.moves += 1
}

function finishMove(level, state, finalPos, collected, path, teleported) {
  const allEmbers = level.emberCells.length === 0 || state.embers === (1 << level.emberCells.length) - 1
  if (allEmbers && finalPos === level.exit) {
    state.status = 'won'
    return { ok: true, state, path, collected, teleported, won: true, died: false }
  }

  advanceTurn(level, state)

  const sentry = sentryAt(level, state, finalPos)
  if (sentry) {
    state.status = 'dead'
    state.deathReason = 'sentry'
    return { ok: true, state, path, collected, teleported, won: false, died: true }
  }

  return { ok: true, state, path, collected, teleported, won: false, died: false }
}

/**
 * Move one turn. Returns ok:false for a bump that should not consume a turn.
 */
export function step(level, state, action) {
  if (!state || state.status !== 'playing') {
    return { ok: false, state, reason: 'over', path: [], collected: [], teleported: false }
  }
  if (action === 'wait') return waitTurn(level, state)

  const dir = DIRS[action]
  if (!dir) return { ok: false, state, reason: 'unknown-action', path: [], collected: [], teleported: false }

  const [dr, dc] = dir
  const width = level.width
  const offset = dr * width + dc
  const next = state.pos + offset
  if (isBlocked(level, state, next)) {
    return { ok: false, state, reason: 'blocked', path: [], collected: [], teleported: false }
  }

  const working = cloneState(state)
  const path = []
  const collected = []
  let current = next
  let teleported = false

  // Leave the tile we are standing on; cracked stone crumbles behind us.
  crumbleAt(level, working, state.pos)

  const visit = (index) => {
    path.push(index)
    collectAt(level, working, index, collected)
  }

  visit(current)

  // Ice carries the spark until the next cell is blocked.
  while (cellChar(level, current) === ICE) {
    const ahead = current + offset
    if (isBlocked(level, working, ahead)) break
    current = ahead
    visit(current)
    if (PORTALS.has(cellChar(level, current))) break
  }

  // Portals are one-way links within the same turn.
  if (PORTALS.has(cellChar(level, current))) {
    const destination = level.portalMap.get(current)
    if (destination !== undefined) {
      const destinationChar = cellChar(level, destination)
      const sentry = sentryAt(level, working, destination)
      if (sentry) {
        // Stepping into an occupied portal is fatal, not a teleport.
        path.push(destination)
        working.pos = destination
        working.moves += 1
        working.turn += 1
        working.status = 'dead'
        working.deathReason = 'sentry'
        return { ok: true, state: working, path, collected, teleported: false, won: false, died: true }
      }
      if (destinationChar !== WALL && destinationChar !== VOID) {
        crumbleAt(level, working, current)
        current = destination
        visit(current)
        teleported = true
      }
    }
  }

  // Every cracked tile crossed on the way (except the final one) is gone.
  for (const index of path) {
    if (index !== current) crumbleAt(level, working, index)
  }

  if (collected.length) {
    working.chain += 1
    if (working.chain > working.maxChain) working.maxChain = working.chain
  } else {
    working.chain = 0
  }
  working.pos = current

  return finishMove(level, working, current, collected, path, teleported)
}

export function waitTurn(level, state) {
  if (!state || state.status !== 'playing') {
    return { ok: false, state, reason: 'over', path: [], collected: [], teleported: false }
  }
  const working = cloneState(state)
  advanceTurn(level, working)
  const sentry = sentryAt(level, working, working.pos)
  if (sentry) {
    working.status = 'dead'
    working.deathReason = 'sentry'
    return { ok: true, state: working, path: [working.pos], collected: [], teleported: false, won: false, died: true }
  }
  return { ok: true, state: working, path: [working.pos], collected: [], teleported: false, won: false, died: false }
}

export function stateKey(level, state) {
  const turn = level.period > 1 ? state.turn % level.period : 0
  return `${state.pos}|${state.embers}|${state.key ? 1 : 0}|${state.crumbled}|${turn}`
}

export function isSolved(level, state) {
  const total = level.emberCells.length
  const all = total === 0 || state.embers === (1 << total) - 1
  return state.status === 'won' || (all && state.pos === level.exit)
}

/**
 * Breadth-first solver. Returns the shortest action sequence, including waits.
 */
export function solveLevel(level, { maxStates = 350000 } = {}) {
  const start = createState(level)
  if (isSolved(level, start)) {
    return { solved: true, moves: 0, actions: [], optimal: 0, states: 1 }
  }
  const queue = [start]
  let head = 0
  const seen = new Set([stateKey(level, start)])
  const parent = new Map([[stateKey(level, start), { prev: null, action: null }]])
  const actions = Object.keys(DIRS)
  if (level.period > 1) actions.push('wait')

  while (head < queue.length) {
    if (seen.size > maxStates) {
      return { solved: false, moves: Infinity, actions: [], optimal: Infinity, states: seen.size, reason: 'state-limit' }
    }
    const current = queue[head++]
    const currentKey = stateKey(level, current)

    for (const action of actions) {
      const result = step(level, current, action)
      if (!result.ok || result.died) continue
      const next = result.state
      const key = stateKey(level, next)
      if (seen.has(key)) continue
      seen.add(key)
      parent.set(key, { prev: currentKey, action })
      if (result.won || isSolved(level, next)) {
        const path = []
        let cursor = key
        while (cursor) {
          const entry = parent.get(cursor)
          if (!entry || entry.action === null) break
          path.push(entry.action)
          cursor = entry.prev
        }
        path.reverse()
        return { solved: true, moves: next.moves, actions: path, optimal: next.moves, states: seen.size }
      }
      queue.push(next)
    }
  }

  return { solved: false, moves: Infinity, actions: [], optimal: Infinity, states: seen.size, reason: 'exhausted' }
}

export function computeLevelScore(level, state, { undoCount = 0 } = {}) {
  const embers = level.emberCells.length
  const base = 300
  const emberPts = embers * 75
  const par = level.par || state.moves
  const efficiency = Math.max(0, par - state.moves) * 30
  const onPar = state.moves <= par ? 200 : 0
  const chain = state.maxChain * 40
  const perfect = level.optimal && state.moves === level.optimal ? 150 : 0
  const penalty = Math.max(0, undoCount) * 20
  const total = Math.max(0, base + emberPts + efficiency + onPar + chain + perfect - penalty)
  return {
    total,
    base,
    emberPts,
    efficiency,
    onPar,
    chain,
    perfect,
    penalty,
    embers,
    moves: state.moves,
    par,
    maxChain: state.maxChain,
  }
}

export function formatMoves(value) {
  return Number.isFinite(value) ? String(value) : '—'
}

/**
 * Deterministic labyrinth generator + validator.
 *
 * A level is generated as a perfect maze, sprinkled with embers, then a
 * feature is added only when the BFS solver can still finish the level.
 * Generated levels are saved as plain ASCII so they are easy to inspect.
 */

import {
  parseLevel,
  solveLevel,
  step,
  createState,
  hashString,
  mulberry32,
  DIRS,
  cellChar,
  ICE,
  PORTAL_A,
  PORTAL_B,
  CRACKED,
  FLAME,
  KEY,
  GATE,
  WALL,
  FLOOR,
  EMBER,
  START,
  EXIT,
  sentryPosition,
} from './rules.mjs'

export const LEVEL_NAMES = [
  'Köz Yolu',
  'Kırık Fener',
  'Buz Çatlağı',
  'Sessiz Geçit',
  'Kül Bahçesi',
  'Alev Kapısı',
  'Kayıp Anahtar',
  'Gölge Kovuğu',
  'Son Ocak',
  'Duman Halkası',
  'Kor Çukuru',
  'Yankı Odası',
  'Sönük Yıldız',
  'Demir Perde',
  'Gece Feneri',
  'Kıvılcım Yolu',
  'Köz Labirenti',
  'Bekçi Geçidi',
  'Küllenen Yol',
  'Fenerin Sırrı',
]

const DIMS = {
  1: [7, 7],
  2: [9, 7],
  3: [9, 9],
  4: [9, 9],
  5: [11, 9],
  6: [11, 9],
  7: [11, 11],
  8: [11, 11],
  9: [13, 11],
  10: [13, 11],
}

function blankGrid(width, height) {
  return Array.from({ length: height }, () => Array(width).fill(WALL))
}

function shuffle(list, rng) {
  for (let i = list.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1))
    ;[list[i], list[j]] = [list[j], list[i]]
  }
  return list
}

function carveMaze(rng, width, height) {
  const grid = blankGrid(width, height)
  const stack = [[1, 1]]
  grid[1][1] = FLOOR
  const dirs = [
    [-2, 0],
    [2, 0],
    [0, -2],
    [0, 2],
  ]
  while (stack.length) {
    const [r, c] = stack[stack.length - 1]
    const options = []
    for (const [dr, dc] of dirs) {
      const nr = r + dr
      const nc = c + dc
      if (nr > 0 && nc > 0 && nr < height - 1 && nc < width - 1 && grid[nr][nc] === WALL) {
        options.push([nr, nc, r + dr / 2, c + dc / 2])
      }
    }
    if (!options.length) {
      stack.pop()
      continue
    }
    const [nr, nc, wr, wc] = options[Math.floor(rng() * options.length)]
    grid[wr][wc] = FLOOR
    grid[nr][nc] = FLOOR
    stack.push([nr, nc])
  }

  // A few loops make the maze feel less like a single corridor.
  const loopChance = 0.075
  for (let r = 1; r < height - 1; r++) {
    for (let c = 1; c < width - 1; c++) {
      if (grid[r][c] !== WALL) continue
      const vertical = r % 2 === 1 && c % 2 === 0 && r > 1 && r < height - 2
      const horizontal = r % 2 === 0 && c % 2 === 1 && c > 1 && c < width - 2
      if ((vertical || horizontal) && rng() < loopChance) grid[r][c] = FLOOR
    }
  }
  return grid
}

function toRows(grid) {
  return grid.map((row) => row.join(''))
}

function openCells(grid) {
  const cells = []
  for (let r = 0; r < grid.length; r++) {
    for (let c = 0; c < grid[0].length; c++) {
      if (grid[r][c] !== WALL) cells.push([r, c])
    }
  }
  return cells
}

function neighbors(grid, r, c) {
  const result = []
  for (const [dr, dc] of Object.values(DIRS)) {
    const nr = r + dr
    const nc = c + dc
    if (nr >= 0 && nc >= 0 && nr < grid.length && nc < grid[0].length && grid[nr][nc] !== WALL) {
      result.push([nr, nc])
    }
  }
  return result
}

function bfs(grid, start) {
  const height = grid.length
  const width = grid[0].length
  const dist = new Map()
  const key = (r, c) => r * width + c
  const queue = [start]
  dist.set(key(...start), 0)
  let head = 0
  while (head < queue.length) {
    const [r, c] = queue[head++]
    const d = dist.get(key(r, c))
    for (const [nr, nc] of neighbors(grid, r, c)) {
      const k = key(nr, nc)
      if (dist.has(k)) continue
      dist.set(k, d + 1)
      queue.push([nr, nc])
    }
  }
  return dist
}

function routeLength(grid, start, embers, exit) {
  const points = [start, ...embers, exit]
  const keys = points.map(([r, c]) => r * grid[0].length + c)
  const matrices = points.map((point) => bfs(grid, point))
  const distance = (i, j) => matrices[i].get(keys[j])
  let best = Infinity
  let bestOrder = embers.map((_, i) => i)
  const indices = embers.map((_, i) => i)
  const permute = (prefix, remaining) => {
    if (!remaining.length) {
      let total = 0
      let cursor = 0
      for (const index of prefix) {
        total += distance(cursor, index + 1)
        cursor = index + 1
      }
      total += distance(cursor, points.length - 1)
      if (total < best) {
        best = total
        bestOrder = [...prefix]
      }
      return
    }
    for (let i = 0; i < remaining.length; i++) {
      const next = remaining[i]
      permute([...prefix, next], [...remaining.slice(0, i), ...remaining.slice(i + 1)])
    }
  }
  if (indices.length <= 6) {
    permute([], indices)
  } else {
    // Greedy fallback for very large ember counts.
    const remaining = new Set(indices)
    let cursor = 0
    let total = 0
    while (remaining.size) {
      let bestIndex = null
      let bestDist = Infinity
      for (const index of remaining) {
        const d = distance(cursor, index + 1)
        if (d < bestDist) {
          bestDist = d
          bestIndex = index
        }
      }
      total += bestDist
      cursor = bestIndex + 1
      remaining.delete(bestIndex)
    }
    total += distance(cursor, points.length - 1)
    best = total
  }
  return { length: best, order: bestOrder }
}

function placeEmbers(grid, start, exit, difficulty, rng) {
  const distanceFromStart = bfs(grid, start)
  const distanceFromExit = bfs(grid, exit)
  const width = grid[0].length
  const key = (r, c) => r * width + c
  const direct = distanceFromStart.get(key(...exit)) || 1
  const wanted = Math.min(6, 3 + Math.floor(difficulty / 3))
  const candidates = openCells(grid).filter(([r, c]) => {
    if ((r === start[0] && c === start[1]) || (r === exit[0] && c === exit[1])) return false
    const ds = distanceFromStart.get(key(r, c))
    const de = distanceFromExit.get(key(r, c))
    return ds >= 2 && de >= 1
  })
  const deadEnds = candidates.filter(([r, c]) => neighbors(grid, r, c).length === 1)
  const pool = [...deadEnds, ...shuffle([...candidates], rng)]

  let best = null
  for (let attempt = 0; attempt < 26; attempt++) {
    shuffle(pool, rng)
    const picked = []
    for (const cell of pool) {
      if (picked.length >= wanted) break
      if (picked.some(([r, c]) => Math.abs(r - cell[0]) + Math.abs(c - cell[1]) < 2)) continue
      if (Math.abs(cell[0] - start[0]) + Math.abs(cell[1] - start[1]) < 2) continue
      if (Math.abs(cell[0] - exit[0]) + Math.abs(cell[1] - exit[1]) < 2) continue
      picked.push(cell)
    }
    if (picked.length < 2) continue
    const route = routeLength(grid, start, picked, exit)
    const ratio = route.length / Math.max(1, direct)
    const score = Math.abs(ratio - 1.75) + (picked.length < wanted ? 0.5 : 0)
    if (!best || score < best.score) best = { embers: picked, route, score, ratio }
  }
  return best
}

function actionsToPath(level, actions) {
  let state = createState(level)
  const path = [state.pos]
  for (const action of actions) {
    const result = step(level, state, action)
    if (!result.ok) break
    path.push(...result.path)
    state = result.state
    if (state.status !== 'playing') break
  }
  return { path, state }
}

function tryLevel(grid, { sentries = [], par = 0 } = {}) {
  try {
    const def = { rows: toRows(grid), sentries }
    const level = parseLevel(def)
    const solution = solveLevel(level, { maxStates: 220000 })
    if (!solution.solved) return null
    level.optimal = solution.optimal
    level.par = par || Math.max(1, Math.min(4, Math.round(solution.optimal * 0.1)))
    return { level, solution }
  } catch {
    return null
  }
}

function findStraightSegments(grid, length, { plainOnly = false } = {}) {
  const segments = []
  const height = grid.length
  const width = grid[0].length
  const allowed = new Set([FLOOR, ICE])
  for (let r = 1; r < height - 1; r++) {
    for (let c = 1; c < width - 1; c++) {
      if (!allowed.has(grid[r][c])) continue
      // Horizontal
      if (c + length <= width - 1) {
        let ok = true
        for (let i = 0; i < length; i++) {
          const ch = grid[r][c + i]
          if (!allowed.has(ch)) {
            ok = false
            break
          }
          if (plainOnly && (grid[r - 1][c + i] !== WALL || grid[r + 1][c + i] !== WALL)) {
            ok = false
            break
          }
        }
        if (ok) segments.push({ cells: Array.from({ length }, (_, i) => [r, c + i]), dir: 'h' })
      }
      // Vertical
      if (r + length <= height - 1) {
        let ok = true
        for (let i = 0; i < length; i++) {
          const ch = grid[r + i][c]
          if (!allowed.has(ch)) {
            ok = false
            break
          }
          if (plainOnly && (grid[r + i][c - 1] !== WALL || grid[r + i][c + 1] !== WALL)) {
            ok = false
            break
          }
        }
        if (ok) segments.push({ cells: Array.from({ length }, (_, i) => [r + i, c]), dir: 'v' })
      }
    }
  }
  return segments
}

function addIce(grid, base, rng) {
  const segments = findStraightSegments(grid, 3, { plainOnly: true }).filter((segment) =>
    segment.cells.every(([r, c]) => [FLOOR].includes(grid[r][c])),
  )
  shuffle(segments, rng)
  for (const segment of segments.slice(0, 12)) {
    const cells = segment.cells
    const start = Math.max(0, Math.floor(rng() * Math.max(1, cells.length - 1)))
    const take = cells.slice(start, start + 2 + Math.floor(rng() * 2))
    if (take.length < 2) continue
    for (const [r, c] of take) grid[r][c] = ICE
    const result = tryLevel(grid, { par: base.par })
    if (result && result.solution.optimal <= base.solution.optimal + 5) return result
    for (const [r, c] of take) grid[r][c] = FLOOR
  }
  return null
}

function addPortals(grid, base, rng) {
  const cells = openCells(grid).filter(([r, c]) => grid[r][c] === FLOOR)
  const deadEnds = cells.filter(([r, c]) => neighbors(grid, r, c).length === 1)
  if (deadEnds.length < 2) return null
  shuffle(deadEnds, rng)
  for (let i = 0; i < deadEnds.length; i++) {
    for (let j = i + 1; j < deadEnds.length; j++) {
      const a = deadEnds[i]
      const b = deadEnds[j]
      const d = Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1])
      if (d < 5) continue
      grid[a[0]][a[1]] = PORTAL_A
      grid[b[0]][b[1]] = PORTAL_B
      const result = tryLevel(grid, { par: base.par })
      if (result && result.solution.optimal <= base.solution.optimal + 10) return result
      grid[a[0]][a[1]] = FLOOR
      grid[b[0]][b[1]] = FLOOR
    }
  }
  return null
}

function addCracked(grid, base, rng) {
  const { path } = actionsToPath(base.level, base.solution.actions)
  const candidates = [...new Set(path)].filter((index) => {
    const r = Math.floor(index / base.level.width)
    const c = index % base.level.width
    return grid[r][c] === FLOOR && index !== base.level.start && index !== base.level.exit
  })
  shuffle(candidates, rng)
  const chosen = candidates.slice(0, 1 + Math.floor(rng() * 2))
  if (!chosen.length) return null
  for (const index of chosen) {
    const r = Math.floor(index / base.level.width)
    const c = index % base.level.width
    grid[r][c] = CRACKED
  }
  const result = tryLevel(grid, { par: base.par })
  if (result) return result
  for (const index of chosen) {
    const r = Math.floor(index / base.level.width)
    const c = index % base.level.width
    grid[r][c] = FLOOR
  }
  return null
}

function addFlames(grid, base, rng) {
  const { path } = actionsToPath(base.level, base.solution.actions)
  const candidates = [...new Set(path)].filter((index) => {
    const r = Math.floor(index / base.level.width)
    const c = index % base.level.width
    return grid[r][c] === FLOOR && index !== base.level.start && index !== base.level.exit
  })
  shuffle(candidates, rng)
  const count = 1 + Math.floor(rng() * 2)
  const chosen = candidates.slice(0, count)
  if (!chosen.length) return null
  for (const index of chosen) {
    const r = Math.floor(index / base.level.width)
    const c = index % base.level.width
    grid[r][c] = FLAME
  }
  const result = tryLevel(grid, { par: base.par })
  if (result) return result
  for (const index of chosen) {
    const r = Math.floor(index / base.level.width)
    const c = index % base.level.width
    grid[r][c] = FLOOR
  }
  return null
}

function addKeyGate(grid, base, rng) {
  const { path } = actionsToPath(base.level, base.solution.actions)
  const pathCells = [...new Set(path)]
  const gateCandidates = pathCells.filter((index) => {
    const r = Math.floor(index / base.level.width)
    const c = index % base.level.width
    return grid[r][c] === FLOOR && index !== base.level.start && index !== base.level.exit
  })
  shuffle(gateCandidates, rng)
  const width = base.level.width
  for (const gateIndex of gateCandidates.slice(0, 8)) {
    const gr = Math.floor(gateIndex / width)
    const gc = gateIndex % width
    grid[gr][gc] = GATE
    // Reachability without the gate.
    const blockedGrid = grid.map((row) => [...row])
    blockedGrid[gr][gc] = WALL
    const reachable = bfs(blockedGrid, [Math.floor(base.level.start / width), base.level.start % width])
    const keyCandidates = openCells(blockedGrid).filter(([r, c]) => {
      const idx = r * width + c
      return grid[r][c] === FLOOR && reachable.has(idx) && idx !== base.level.start && idx !== base.level.exit
    })
    shuffle(keyCandidates, rng)
    for (const [kr, kc] of keyCandidates.slice(0, 12)) {
      grid[kr][kc] = KEY
      const result = tryLevel(grid, { par: base.par })
      if (result) return result
      grid[kr][kc] = FLOOR
    }
    grid[gr][gc] = FLOOR
  }
  return null
}

function addSentry(grid, base, rng) {
  const segments = findStraightSegments(grid, 4, { plainOnly: true }).filter((segment) =>
    segment.cells.every(([r, c]) => grid[r][c] === FLOOR),
  )
  shuffle(segments, rng)
  for (const segment of segments.slice(0, 10)) {
    const cells = segment.cells.slice(0, 4 + Math.floor(rng() * 3))
    if (cells.length < 4) continue
    const sentry = { path: cells, mode: 'pingpong', startIndex: Math.floor(rng() * cells.length) }
    const result = tryLevel(grid, { sentries: [sentry], par: base.par })
    if (result) return result
  }
  return null
}

function addSecondSentry(grid, base, rng) {
  const segments = findStraightSegments(grid, 3, { plainOnly: true }).filter((segment) =>
    segment.cells.every(([r, c]) => grid[r][c] === FLOOR),
  )
  shuffle(segments, rng)
  for (const segment of segments.slice(0, 12)) {
    const cells = segment.cells.slice(0, 3 + Math.floor(rng() * 2))
    if (cells.length < 3) continue
    const sentries = [...base.level.sentries.map((s) => ({ path: s.path, mode: s.mode, startIndex: s.startIndex })), { path: cells, mode: 'pingpong', startIndex: Math.floor(rng() * cells.length) }]
    const result = tryLevel(grid, { sentries, par: base.par })
    if (result) return result
  }
  return null
}

/**
 * Generate one validated level. Returns null when this seed cannot produce a
 * clean level (the caller should retry with another seed).
 */
export function generateLevel({ seed = 'seed', difficulty = 1, name = '', id = '' } = {}) {
  const rng = mulberry32(hashString(seed))
  const levelDifficulty = Math.max(1, Math.min(10, difficulty))
  const [width, height] = DIMS[levelDifficulty] || DIMS[5]
  const grid = carveMaze(rng, width, height)
  const cells = openCells(grid)
  if (cells.length < 12) return null

  const start = cells[Math.floor(rng() * Math.min(cells.length, 6))]
  const distances = bfs(grid, start)
  let exit = start
  let farthest = -1
  for (const [r, c] of cells) {
    const d = distances.get(r * width + c) || 0
    if (d > farthest) {
      farthest = d
      exit = [r, c]
    }
  }
  if (farthest < 6) return null

  const picked = placeEmbers(grid, start, exit, levelDifficulty, rng)
  if (!picked || picked.embers.length < 2) return null

  grid[start[0]][start[1]] = START
  grid[exit[0]][exit[1]] = EXIT
  for (const [r, c] of picked.embers) grid[r][c] = EMBER

  let base = tryLevel(grid)
  if (!base) return null

  if (levelDifficulty >= 3) {
    const ice = addIce(grid, base, rng)
    if (ice) base = ice
  }
  if (levelDifficulty >= 4) {
    const portals = addPortals(grid, base, rng)
    if (portals) base = portals
  }
  if (levelDifficulty >= 5) {
    const cracked = addCracked(grid, base, rng)
    if (cracked) base = cracked
  }
  if (levelDifficulty >= 6) {
    const flames = addFlames(grid, base, rng)
    if (flames) base = flames
  }
  if (levelDifficulty >= 7) {
    const keyGate = addKeyGate(grid, base, rng)
    if (keyGate) base = keyGate
  }
  if (levelDifficulty >= 8) {
    const sentry = addSentry(grid, base, rng)
    if (sentry) base = sentry
  }
  if (levelDifficulty >= 10) {
    const second = addSecondSentry(grid, base, rng)
    if (second) base = second
  }

  const final = tryLevel(grid, { sentries: base.level.sentries.map((s) => ({ path: s.path, mode: s.mode, startIndex: s.startIndex })) })
  if (!final) return null

  const emberCount = final.level.emberCells.length
  const par = Math.max(final.solution.optimal + 1, Math.round(final.solution.optimal * 1.12))
  const featureList = []
  if (grid.flat().includes(ICE)) featureList.push('ice')
  if (grid.flat().includes(PORTAL_A)) featureList.push('portal')
  if (grid.flat().includes(CRACKED)) featureList.push('cracked')
  if (grid.flat().includes(FLAME)) featureList.push('flame')
  if (grid.flat().includes(KEY)) featureList.push('key')
  if (final.level.sentries.length) featureList.push('sentry')

  const nameIndex = (hashString(seed) + levelDifficulty) % LEVEL_NAMES.length
  return {
    id: id || `gen-${seed}`,
    name: name || LEVEL_NAMES[nameIndex],
    rows: toRows(grid),
    par,
    optimal: final.solution.optimal,
    difficulty: levelDifficulty,
    features: featureList,
    embers: emberCount,
    sentries: final.level.sentries.map((s) => ({ path: s.path, mode: s.mode, startIndex: s.startIndex })),
    seed,
  }
}

/**
 * Try a handful of seeds until a valid level is produced.
 */
export function generateStable({ seed, difficulty, name, id, attempts = 12 } = {}) {
  for (let i = 0; i < attempts; i++) {
    const candidate = generateLevel({
      seed: `${seed}::${i}`,
      difficulty,
      name,
      id,
    })
    if (candidate) return candidate
  }
  return null
}

