414: /**
415:  * Breadth-first solver. Returns the shortest action sequence, including waits.
416:  */
417: export function solveLevel(level, { maxStates = 350000 } = {}) {
418:   const start = createState(level)
419:   if (isSolved(level, start)) {
420:     return { solved: true, moves: 0, actions: [], optimal: 0, states: 1 }
421:   }
422:   const queue = [start]
423:   let head = 0
424:   const seen = new Set([stateKey(level, start)])
425:   const parent = new Map([[stateKey(level, start), { prev: null, action: null }]])
426:   const actions = Object.keys(DIRS)
427:   if (level.period > 1) actions.push('wait')
428: 
429:   while (head < queue.length) {
430:     if (seen.size > maxStates) {
431:       return { solved: false, moves: Infinity, actions: [], optimal: Infinity, states: seen.size, reason: 'state-limit' }
432:     }
433:     const current = queue[head++]
434:     const currentKey = stateKey(level, current)
435: 
436:     for (const action of actions) {
437:       const result = step(level, current, action)
438:       if (!result.ok || result.died) continue
439:       const next = result.state
440:       const key = stateKey(level, next)
441:       if (seen.has(key)) continue
442:       seen.add(key)
443:       parent.set(key, { prev: currentKey, action })
444:       if (result.won || isSolved(level, next)) {
445:         const path = []
446:         let cursor = key
447:         while (cursor) {
448:           const entry = parent.get(cursor)
449:           if (!entry || entry.action === null) break
450:           path.push(entry.action)
451:           cursor = entry.prev
452:         }
453:         path.reverse()
454:         return { solved: true, moves: next.moves, actions: path, optimal: next.moves, states: seen.size }
455:       }
456:       queue.push(next)
457:     }
458:   }
459: 
460:   return { solved: false, moves: Infinity, actions: [], optimal: Infinity, states: seen.size, reason: 'exhausted' }
461: }
462: 
463: export function computeLevelScore(level, state, { undoCount = 0 } = {}) {
464:   const embers = level.emberCells.length
465:   const base = 300
466:   const emberPts = embers * 75
467:   const par = level.par || state.moves
468:   const efficiency = Math.max(0, par - state.moves) * 30
469:   const onPar = state.moves <= par ? 200 : 0
470:   const chain = state.maxChain * 40
471:   const perfect = level.optimal && state.moves === level.optimal ? 150 : 0
472:   const penalty = Math.max(0, undoCount) * 20
473:   const total = Math.max(0, base + emberPts + efficiency + onPar + chain + perfect - penalty)
474:   return {
475:     total,
476:     base,
477:     emberPts,
478:     efficiency,
479:     onPar,
480:     chain,
481:     perfect,
482:     penalty,
483:     embers,
484:     moves: state.moves,
485:     par,
486:     maxChain: state.maxChain,
487:   }
488: }
