/* ---------- Ambient background ---------- */

.ambient {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
  background:
    radial-gradient(ellipse 90% 60% at 50% -10%, rgba(36, 63, 84, 0.4), transparent 65%),
    radial-gradient(ellipse 70% 50% at 100% 100%, rgba(32, 20, 44, 0.5), transparent 70%),
    linear-gradient(180deg, #060b13 0%, #04070c 55%, #030509 100%);
}

.ambient-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.5;
  animation: orb-drift 26s var(--ease) infinite alternate;
}

.orb-amber {
  width: 44vw;
  height: 44vw;
  top: -18vw;
  right: 6vw;
  background: radial-gradient(circle, rgba(255, 132, 39, 0.2), rgba(255, 120, 30, 0.03) 55%, transparent 70%);
}

.orb-teal {
  width: 38vw;
  height: 38vw;
  bottom: -18vw;
  left: -8vw;
  background: radial-gradient(circle, rgba(64, 226, 206, 0.14), rgba(40, 190, 180, 0.02) 55%, transparent 70%);
  animation-delay: -9s;
}

.orb-violet {
  width: 30vw;
  height: 30vw;
  top: 34%;
  left: 42%;
  background: radial-gradient(circle, rgba(148, 106, 240, 0.1), transparent 68%);
  animation-delay: -15s;
}

.ambient-grid {
  position: absolute;
  inset: 0;
  opacity: 0.2;
  background-image:
    linear-gradient(rgba(143, 190, 212, 0.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(143, 190, 212, 0.055) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: radial-gradient(ellipse 80% 70% at 50% 40%, #000 20%, transparent 78%);
  -webkit-mask-image: radial-gradient(ellipse 80% 70% at 50% 40%, #000 20%, transparent 78%);
}

.ambient-noise {
  position: absolute;
  inset: 0;
  opacity: 0.16;
  background-image: radial-gradient(rgba(255, 255, 255, 0.16) 0.5px, transparent 0.5px);
  background-size: 4px 4px;
  mix-blend-mode: soft-light;
}

@keyframes orb-drift {
  from {
    transform: translate3d(0, 0, 0) scale(1);
