  border-color: rgba(255, 180, 92, 0.28);
}

.net-status.is-connecting .net-dot {
  background: var(--amber);
  box-shadow: 0 0 0 3px rgba(255, 180, 92, 0.12), 0 0 10px rgba(255, 180, 92, 0.7);
  animation: dot-blink 1.1s ease-in-out infinite;
}

.net-status.is-offline {
  color: #c5a2a7;
}

.net-status.is-offline .net-dot {
  background: #ff6b7a;
  box-shadow: 0 0 0 3px rgba(255, 107, 122, 0.1);
}

@keyframes dot-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.55;
  }
}

@keyframes dot-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.25;
  }
}

.icon-btn {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: rgba(12, 20, 32, 0.62);
  color: var(--muted);
  transition: color 0.2s, border-color 0.2s, background 0.2s, transform 0.2s;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.icon-btn:hover {
  color: var(--amber-soft);
  border-color: var(--line-warm);
  background: rgba(26, 35, 48, 0.8);
  transform: translateY(-1px);
}

.icon-btn svg {
  width: 19px;
  height: 19px;
}

.icon-btn .icon-muted {
  display: none;
}

.icon-btn.is-muted .icon-sound {
  display: none;
}

.icon-btn.is-muted .icon-muted {
  display: block;
}

.question-mark {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  line-height: 1;
}

/* ---------- Layout ---------- */

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(330px, 386px);
  gap: clamp(14px, 1.8vw, 22px);
  align-items: start;
  flex: 1;
}

.panel {
  position: relative;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background:
    linear-gradient(155deg, rgba(23, 36, 52, 0.55), rgba(9, 15, 24, 0.82) 55%),
    var(--panel);
  box-shadow: var(--shadow-soft);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  overflow: hidden;
}

.panel::before {
  content: '';
  position: absolute;
  inset: 0 0 auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 196, 120, 0.28), rgba(103, 243, 222, 0.14), transparent);
  pointer-events: none;
}

.board-panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: clamp(14px, 1.6vw, 22px);
  min-height: 0;
}

.side {
  display: grid;
  gap: 14px;
  min-width: 0;
}

/* ---------- Board header ---------- */

.board-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}

.level-meta {
  min-width: 0;
}

.level-kicker {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 7px;
}

.mode-pill {
  display: inline-flex;
  align-items: center;
  height: 21px;
  padding: 0 9px;
  border-radius: 999px;
  border: 1px solid rgba(255, 180, 92, 0.3);
  background: rgba(255, 160, 70, 0.09);
  color: var(--amber);
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.mode-pill.is-campaign {
  border-color: rgba(103, 243, 222, 0.28);
  background: rgba(103, 243, 222, 0.07);
  color: var(--teal);
}

.level-index {
  color: var(--faint);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.14em;
}

.level-meta h2 {
  font-family: var(--font-display);
  font-size: clamp(1.35rem, 2.4vw, 1.85rem);
  font-weight: 600;
  letter-spacing: 0.04em;
  line-height: 1.12;
  color: #f4e8d4;
}

.level-meta #level-sub {
  margin-top: 5px;
  color: var(--muted);
  font-size: 0.8rem;
  max-width: 54ch;
}

.run-stats {
  display: flex;
  align-items: stretch;
  gap: 6px;
  flex: 0 0 auto;
}

.stat {
  min-width: 58px;
  padding: 7px 10px 6px;
  border-radius: 11px;
  border: 1px solid var(--line-soft);
  background: rgba(5, 10, 17, 0.44);
  text-align: center;
}

.stat span {
  display: block;
  font-family: var(--font-display);
  font-size: 1.12rem;
  font-weight: 700;
  line-height: 1.15;
  color: #f1e6d2;
  font-variant-numeric: tabular-nums;
}

.stat small {
  display: block;
  margin-top: 2px;
  color: var(--faint);
  font-size: 0.55rem;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.cans-stat span {
  color: var(--amber-soft);
}

.cans-stat.is-low {
  border-color: rgba(255, 92, 110, 0.34);
  background: rgba(255, 92, 110, 0.08);
}

.cans-stat.is-low span {
  color: #ff8b97;
}

/* ---------- Board ---------- */

.board-wrap {
  position: relative;
  flex: 1;
  min-height: clamp(360px, 54vh, 640px);
  border-radius: 15px;
  border: 1px solid rgba(140, 185, 210, 0.12);
  background: #04080e;
  overflow: hidden;
  isolation: isolate;
  box-shadow: inset 0 0 60px rgba(0, 0, 0, 0.5), 0 10px 30px rgba(0, 0, 0, 0.3);
}

.board-wrap::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.025);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent 18%, transparent 82%, rgba(0, 0, 0, 0.22));
}

#board {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: crosshair;
}

.chain-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 11px;
  border-radius: 999px;
  border: 1px solid rgba(255, 180, 92, 0.38);
  background: rgba(20, 15, 10, 0.8);
  color: var(--amber-pale);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  opacity: 0;
  transform: translateY(-6px) scale(0.94);
  transition: opacity 0.25s, transform 0.25s;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  pointer-events: none;
}

.chain-badge.is-visible {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.chain-icon {
  color: var(--amber);
  font-size: 0.9rem;
  filter: drop-shadow(0 0 6px rgba(255, 170, 70, 0.7));
}

.chain-badge strong {
  font-family: var(--font-display);
  font-size: 0.9rem;
  color: var(--amber-soft);
}

.board-corner-hint {
  position: absolute;
  right: 12px;
  bottom: 10px;
  z-index: 2;
  padding: 4px 9px;
  border-radius: 999px;
  background: rgba(4, 8, 14, 0.55);
  border: 1px solid rgba(152, 194, 218, 0.09);
  color: var(--faint);
  font-size: 0.63rem;
  letter-spacing: 0.04em;
  pointer-events: none;
  transition: opacity 0.3s;
}

.board-corner-hint.is-hidden {
  opacity: 0;
}

/* ---------- Board footer ---------- */

.board-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
}

.objective-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.objective-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 32px;
  padding: 0 11px;
  border-radius: 999px;
  border: 1px solid var(--line-soft);
  background: rgba(5, 10, 17, 0.4);
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 600;
  white-space: nowrap;
  transition: color 0.25s, border-color 0.25s, background 0.25s;
}

.objective-chip strong {
  color: #f0e4d0;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.objective-chip.is-done {
  border-color: rgba(103, 243, 222, 0.26);
  background: rgba(103, 243, 222, 0.06);
  color: #a9ded6;
}

.objective-chip.is-done strong {
  color: var(--teal);
}

.objective-chip.is-open {
  border-color: rgba(255, 180, 92, 0.34);
  background: rgba(255, 170, 70, 0.08);
  color: var(--amber-soft);
}

.objective-icon {
  width: 13px;
  height: 13px;
  flex: 0 0 auto;
  display: inline-block;
}

.ember-icon {
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, #fff8e4, #ffc268 42%, #ff6d1a 100%);
  box-shadow: 0 0 10px rgba(255, 150, 50, 0.7);
}

.exit-icon {
  position: relative;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 180, 92, 0.45);
}

.exit-icon::after {
  content: '';
  position: absolute;
  inset: 3.5px;
  border-radius: 50%;
  background: rgba(255, 180, 92, 0.3);
}

.objective-chip.is-open .exit-icon {
  border-color: var(--amber);
  box-shadow: 0 0 12px rgba(255, 160, 60, 0.7);
}

.objective-chip.is-open .exit-icon::after {
  background: var(--amber-pale);
}

.board-actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

.text-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 31px;
  padding: 0 10px;
  border-radius: 9px;
  border: 1px solid var(--line);
  background: rgba(12, 20, 32, 0.5);
  color: var(--muted);
  font-size: 0.7rem;
  font-weight: 600;
  transition: color 0.2s, border-color 0.2s, background 0.2s;
}

.text-btn:hover:not(:disabled) {
  color: var(--amber-soft);
  border-color: var(--line-warm);
  background: rgba(26, 35, 48, 0.7);
}

.text-btn:disabled {
  opacity: 0.36;
}

.text-btn.small {
  height: 26px;
  padding: 0 8px;
  font-size: 0.65rem;
}

kbd {
  display: inline-grid;
  place-items: center;
  min-width: 16px;
  height: 16px;
  padding: 0 3px;
  border-radius: 4px;
  border: 1px solid rgba(152, 194, 218, 0.16);
  background: rgba(255, 255, 255, 0.04);
  color: var(--faint);
  font-family: var(--font-body);
  font-size: 0.58rem;
  line-height: 1;
}

/* ---------- D-pad ---------- */

.dpad {
  display: none;
  grid-template-columns: repeat(3, minmax(48px, 64px));
  grid-template-rows: repeat(3, minmax(44px, 52px));
  grid-template-areas:
    '. up .'
    'left wait right'
    '. down .';
  gap: 6px;
  justify-content: center;
  padding-top: 2px;
}

.dpad-btn {
  display: grid;
  place-items: center;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(31, 46, 64, 0.7), rgba(9, 16, 26, 0.85));
  color: #d7e2e8;
  font-size: 1.05rem;
  font-weight: 600;
  box-shadow: 0 5px 14px rgba(0, 0, 0, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  user-select: none;
  touch-action: manipulation;
  transition: transform 0.08s, border-color 0.15s, background 0.15s;
}

.dpad-btn:hover {
  border-color: var(--line-warm);
}

.dpad-btn:active {
  transform: scale(0.94);
  background: linear-gradient(180deg, rgba(255, 170, 70, 0.22), rgba(40, 27, 14, 0.9));
  border-color: rgba(255, 180, 92, 0.4);
}

.dpad-btn.up {
  grid-area: up;
}
.dpad-btn.left {
  grid-area: left;
}
.dpad-btn.wait {
  grid-area: wait;
  font-size: 0.63rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--amber-soft);
}
.dpad-btn.right {
  grid-area: right;
}
.dpad-btn.down {
  grid-area: down;
}

/* ---------- Mission panel ---------- */

.mission-panel {
  padding: 17px 17px 15px;
}

.panel-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.eyebrow {
  display: block;
  color: var(--faint);
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.24em;
  text-transform: uppercase;
}

.panel-heading h3 {
  margin-top: 3px;
  font-family: var(--font-display);
  font-size: 1.06rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: #f0e5d3;
}

.mission-score {
  text-align: right;
  flex: 0 0 auto;
}

.mission-score span {
  display: block;
  font-family: var(--font-display);
  font-size: 1.36rem;
  font-weight: 700;
  line-height: 1.05;
  color: var(--amber-soft);
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 20px rgba(255, 170, 70, 0.25);
}

.mission-score small {
  color: var(--faint);
  font-size: 0.56rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.mission-list {
  list-style: none;
  margin: 14px 0 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.mission-list li {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  color: var(--muted);
  font-size: 0.76rem;
  line-height: 1.4;
  transition: color 0.25s;
}

.mission-list li strong {
  color: #e8dcc8;
  font-weight: 700;
}

.mission-list li.is-done {
  color: #8fbdb4;
}

.mission-list li.is-done strong {
  color: var(--teal);
}

.mission-bullet {
  width: 7px;
  height: 7px;
  flex: 0 0 auto;
  margin-top: 5px;
  border-radius: 2px;
  border: 1px solid rgba(255, 180, 92, 0.4);
  background: rgba(255, 180, 92, 0.08);
  transform: rotate(45deg);
  transition: background 0.25s, border-color 0.25s, box-shadow 0.25s;
}

.mission-list li.is-done .mission-bullet {
  border-color: rgba(103, 243, 222, 0.7);
  background: var(--teal);
  box-shadow: 0 0 8px rgba(103, 243, 222, 0.5);
}

.chain-meter {
  margin-top: 15px;
  padding-top: 13px;
  border-top: 1px solid var(--line-soft);
}

.chain-meter-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--faint);
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.chain-meter-head span:last-child {
  color: var(--amber-soft);
  font-family: var(--font-display);
  font-size: 0.85rem;
  letter-spacing: 0;
}

.chain-track {
  height: 5px;
  margin-top: 7px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.055);
  overflow: hidden;
}

.chain-track span {
  display: block;
  height: 100%;
  width: 0%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ff7b24, #ffcf79 70%, #fff1c9);
  box-shadow: 0 0 12px rgba(255, 160, 60, 0.55);
  transition: width 0.3s var(--ease);
}

.chain-meter p {
  margin-top: 7px;
  color: var(--faint);
  font-size: 0.66rem;
  line-height: 1.35;
}

.level-dots {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 14px;
  flex-wrap: wrap;
}

.level-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: 1px solid rgba(152, 194, 218, 0.22);
  background: rgba(255, 255, 255, 0.03);
  transition: background 0.25s, border-color 0.25s, box-shadow 0.25s, transform 0.25s;
}

.level-dot.is-done {
  border-color: rgba(103, 243, 222, 0.5);
  background: rgba(103, 243, 222, 0.65);
}

.level-dot.is-current {
  border-color: var(--amber);
  background: var(--amber);
  box-shadow: 0 0 0 3px rgba(255, 180, 92, 0.14), 0 0 10px rgba(255, 180, 92, 0.6);
  transform: scale(1.1);
}

.level-dot.is-locked {
  opacity: 0.35;
}

/* ---------- Leaderboard ---------- */

.leaderboard-panel {
  padding: 17px 15px 13px;
}

.week-badge {
  flex: 0 0 auto;
  padding: 4px 8px;
  border-radius: 6px;
  border: 1px solid var(--line);
  background: rgba(5, 10, 17, 0.4);
  color: var(--faint);
  font-family: var(--font-display);
  font-size: 0.62rem;
  letter-spacing: 0.05em;
}

.lb-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
  margin-top: 13px;
  padding: 3px;
  border-radius: 10px;
  border: 1px solid var(--line-soft);
  background: rgba(4, 8, 14, 0.5);
}

.lb-tab {
  height: 28px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--faint);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  transition: color 0.2s, background 0.2s, box-shadow 0.2s;
}

.lb-tab:hover {
  color: var(--muted);
}

.lb-tab.is-active {
  color: #f2e6d1;
  background: linear-gradient(180deg, rgba(54, 67, 82, 0.7), rgba(27, 37, 51, 0.7));
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.08), 0 3px 10px rgba(0, 0, 0, 0.25);
}

.lb-list {
  margin-top: 10px;
  max-height: 348px;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: rgba(152, 194, 218, 0.2) transparent;
  padding-right: 2px;
}

.lb-list::-webkit-scrollbar {
  width: 5px;
}

.lb-list::-webkit-scrollbar-thumb {
  background: rgba(152, 194, 218, 0.2);
  border-radius: 999px;
}

.lb-row {
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  padding: 7px 8px;
  border-radius: 9px;
  border: 1px solid transparent;
  transition: background 0.2s, border-color 0.2s;
}

.lb-row + .lb-row {
  margin-top: 2px;
}

.lb-row:hover {
  background: rgba(255, 255, 255, 0.028);
}

.lb-rank {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 6px;
  color: var(--faint);
  font-family: var(--font-display);
  font-size: 0.72rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.lb-row.rank-1 .lb-rank {
  color: #241605;
  background: linear-gradient(180deg, #ffe2a5, #ffb14a);
  box-shadow: 0 0 12px rgba(255, 180, 92, 0.32);
}

.lb-row.rank-2 .lb-rank {
  color: #101820;
  background: linear-gradient(180deg, #dfe9ee, #a9bcc8);
}

.lb-row.rank-3 .lb-rank {
  color: #1b1208;
  background: linear-gradient(180deg, #e8b88a, #b97a45);
}

.lb-main {
  min-width: 0;
}

.lb-name {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #dde8ec;
  font-size: 0.76rem;
  font-weight: 700;
  line-height: 1.25;
}

.lb-meta {
  display: block;
  margin-top: 1px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--faint);
  font-size: 0.59rem;
  letter-spacing: 0.02em;
}

.lb-score {
  color: var(--amber-soft);
  font-family: var(--font-display);
  font-size: 0.82rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.lb-row.is-ghost {
  opacity: 0.72;
}

.lb-row.is-ghost .lb-name::after {
  content: ' ◇';
  color: rgba(180, 140, 255, 0.8);
  font-size: 0.62rem;
}

.lb-row.is-player {
  border-color: rgba(103, 243, 222, 0.26);
  background: linear-gradient(90deg, rgba(103, 243, 222, 0.1), rgba(103, 243, 222, 0.015));
}

.lb-row.is-player .lb-name {
  color: #b9fff3;
}

.lb-row.is-player .lb-score {
  color: var(--teal);
}

.lb-row.is-locked {
  opacity: 0.42;
}

.lb-row.is-locked .lb-score {
  color: var(--faint);
}

.lb-empty {
  padding: 24px 12px;
  text-align: center;
  color: var(--faint);
  font-size: 0.72rem;
  line-height: 1.5;
}

.lb-legend {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--line-soft);
  color: var(--faint);
  font-size: 0.59rem;
  line-height: 1.4;
}

.legend-ghost {
  color: rgba(180, 140, 255, 0.85);
  margin-right: 3px;
}

.lb-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 7px;
}

.lb-sync {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--faint);
  font-size: 0.6rem;
  letter-spacing: 0.03em;
}

.sync-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--faint);
}

.lb-sync.is-online .sync-dot {
  background: var(--teal);
  box-shadow: 0 0 8px rgba(103, 243, 222, 0.7);
}

.lb-sync.is-online {
  color: #93c9c1;
}

.lb-sync.is-syncing .sync-dot {
  background: var(--amber);
  animation: dot-blink 1.1s infinite;
}

/* ---------- Tip & footer ---------- */

.tip-panel {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px 15px;
  border-color: rgba(255, 180, 92, 0.14);
  background:
    linear-gradient(120deg, rgba(255, 160, 60, 0.06), rgba(9, 15, 24, 0.7) 55%),
    var(--panel);
}

.tip-mark {
  color: var(--amber);
  font-size: 0.9rem;
  line-height: 1.35;
  filter: drop-shadow(0 0 7px rgba(255, 170, 70, 0.6));
}

.tip-panel p {
  color: var(--muted);
  font-size: 0.7rem;
  line-height: 1.45;
}

.site-foot {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  flex-wrap: wrap;
  padding: 2px 6px 4px;
  color: var(--faint);
  font-size: 0.64rem;
  letter-spacing: 0.02em;
  text-align: center;
}

.foot-sep {
  opacity: 0.5;
}

.link-btn {
  padding: 0;
  border: 0;
  background: none;
  color: #bfae92;
  font-size: inherit;
  text-decoration: underline;
  text-decoration-color: rgba(255, 180, 92, 0.32);
  text-underline-offset: 3px;
  transition: color 0.2s, text-decoration-color 0.2s;
}

.link-btn:hover {
  color: var(--amber-soft);
  text-decoration-color: var(--amber);
}

/* ---------- Buttons ---------- */

.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  height: 46px;
  padding: 0 20px;
  border-radius: 12px;
  border: 1px solid transparent;
  font-size: 0.8rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  transition: transform 0.2s var(--ease), box-shadow 0.2s, border-color 0.2s, background 0.2s;
  white-space: nowrap;
}

.btn:hover {
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(0) scale(0.985);
}

.btn-primary {
  color: #241404;
  background: linear-gradient(180deg, #ffd28b, #ffad4c 55%, #f08b25);
  border-color: rgba(255, 220, 160, 0.6);
  box-shadow: 0 10px 26px rgba(255, 130, 30, 0.24), inset 0 1px 0 rgba(255, 255, 255, 0.5);
}

.btn-primary:hover {
  box-shadow: 0 14px 34px rgba(255, 130, 30, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.5);
}

.btn-ghost {
  color: #d4c7b2;
  border-color: rgba(255, 180, 92, 0.22);
  background: rgba(255, 170, 70, 0.045);
}

.btn-ghost:hover {
  border-color: rgba(255, 180, 92, 0.44);
  background: rgba(255, 170, 70, 0.09);
  color: var(--amber-soft);
}

.btn-soft {
  color: #c9d9df;
  border-color: var(--line);
  background: rgba(16, 26, 39, 0.75);
}

.btn-soft:hover {
  border-color: rgba(152, 194, 218, 0.26);
  background: rgba(25, 38, 55, 0.85);
}

.btn-danger {
  color: #ffc2c8;
  border-color: rgba(255, 92, 110, 0.3);
  background: rgba(255, 92, 110, 0.08);
}

.btn-danger:hover {
  border-color: rgba(255, 92, 110, 0.55);
  background: rgba(255, 92, 110, 0.14);
}

.btn-arrow {
  font-size: 1.05rem;
  line-height: 1;
  transition: transform 0.2s var(--ease);
}

.btn:hover .btn-arrow {
  transform: translateX(3px);
}

.btn:disabled {
  opacity: 0.45;
  transform: none;
}

/* ---------- Intro overlay ---------- */

.intro {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
  align-items: center;
  gap: clamp(24px, 5vw, 80px);
  padding: clamp(20px, 5vw, 64px);
  background:
    radial-gradient(ellipse 60% 55% at 22% 45%, rgba(38, 62, 82, 0.55), transparent 70%),
    radial-gradient(ellipse 45% 45% at 88% 60%, rgba(255, 126, 34, 0.12), transparent 70%),
    linear-gradient(120deg, rgba(4, 8, 13, 0.92), rgba(5, 9, 15, 0.88));
  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);
  transition: opacity 0.45s var(--ease), visibility 0.45s;
  overflow-y: auto;
}

.intro.is-hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.intro-card {
  position: relative;
  width: min(620px, 100%);
  justify-self: end;
  padding: clamp(26px, 4vw, 46px);
  border-radius: 26px;
  border: 1px solid rgba(255, 180, 92, 0.17);
  background:
    linear-gradient(155deg, rgba(24, 38, 54, 0.8), rgba(8, 14, 23, 0.92) 60%),
    rgba(9, 15, 24, 0.9);
  box-shadow: 0 40px 100px rgba(0, 0, 0, 0.62), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  animation: intro-rise 0.8s var(--ease) both;
}

.intro-card::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: radial-gradient(ellipse 80% 50% at 50% 0%, rgba(255, 170, 70, 0.09), transparent 60%);
}

@keyframes intro-rise {
  from {
    opacity: 0;
    transform: translateY(22px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.intro-ornament {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 20px;
}

.intro-ornament span {
  display: block;
  height: 1px;
  background: linear-gradient(90deg, rgba(255, 180, 92, 0.6), transparent);
}

.intro-ornament span:nth-child(1) {
  width: 34px;
}

.intro-ornament span:nth-child(2) {
  width: 7px;
  height: 7px;
  background: var(--amber);
  transform: rotate(45deg);
  box-shadow: 0 0 10px rgba(255, 170, 70, 0.8);
}

.intro-ornament span:nth-child(3) {
  width: 34px;
  background: linear-gradient(90deg, transparent, rgba(255, 180, 92, 0.6));
}

.intro-eyebrow {
  color: var(--amber);
  opacity: 0.9;
}

.intro-card h2 {
  margin-top: 12px;
  font-family: var(--font-display);
  font-size: clamp(2rem, 4.4vw, 3.2rem);
  font-weight: 600;
  line-height: 1.08;
  letter-spacing: 0.015em;
  color: #f5ead7;
}

.intro-card h2 em {
  font-style: normal;
  color: var(--amber-soft);
  text-shadow: 0 0 34px rgba(255, 150, 50, 0.35);
}

.intro-lead {
  margin-top: 16px;
  max-width: 52ch;
  color: var(--muted);
  font-size: 0.92rem;
  line-height: 1.65;
}

.intro-features {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  margin-top: 20px;
}

.intro-features span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #b8c7ce;
  font-size: 0.69rem;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.feature-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  display: inline-block;
}

.feature-dot.amber {
  background: var(--amber);
  box-shadow: 0 0 8px rgba(255, 180, 92, 0.8);
}

.feature-dot.teal {
  background: var(--teal);
  box-shadow: 0 0 8px rgba(103, 243, 222, 0.8);
}

.feature-dot.violet {
  background: var(--violet);
  box-shadow: 0 0 8px rgba(180, 140, 255, 0.8);
}

.intro-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 28px;
}

.intro-actions .btn-primary {
  flex: 1 1 240px;
  height: 52px;
  justify-content: space-between;
  padding: 0 22px;
}

.intro-actions .btn-ghost {
  flex: 0 1 150px;
  height: 52px;
}

.intro-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 18px;
  color: var(--faint);
  font-size: 0.65rem;
}

.meta-sep {
  opacity: 0.5;
}

.intro-side {
  position: relative;
  justify-self: start;
  width: min(430px, 100%);
  aspect-ratio: 1;
  display: grid;
  place-items: center;
  animation: intro-rise 1s 0.12s var(--ease) both;
}

.intro-side-ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid rgba(255, 180, 92, 0.16);
}

.ring-one {
  inset: 8%;
  border-style: dashed;
  border-color: rgba(255, 180, 92, 0.18);
  animation: ring-spin 60s linear infinite;
}

.ring-two {
  inset: 23%;
  border-color: rgba(103, 243, 222, 0.13);
  animation: ring-spin 44s linear infinite reverse;
}

@keyframes ring-spin {
  to {
    transform: rotate(360deg);
  }
}

.intro-side-spark {
  position: relative;
  width: 26%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, #fffdf3 0%, #ffe2a0 22%, #ffb14a 48%, #ff6a1a 74%, rgba(255, 90, 20, 0.05) 100%);
  box-shadow:
    0 0 60px rgba(255, 150, 50, 0.5),
    0 0 140px rgba(255, 120, 30, 0.28),
    0 0 220px rgba(255, 110, 20, 0.14);
  animation: spark-breathe 5s ease-in-out infinite;
}

.intro-side-spark::before,
.intro-side-spark::after {
  content: '';
  position: absolute;
  inset: -46%;
  border-radius: 50%;
  border: 1px solid rgba(255, 190, 100, 0.14);
}

.intro-side-spark::after {
  inset: -86%;
  border-color: rgba(255, 190, 100, 0.08);
}

@keyframes spark-breathe {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.06);
  }
}

.intro-side-caption {
  position: absolute;
  bottom: 4%;
  color: rgba(214, 199, 175, 0.5);
  font-family: var(--font-display);
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  line-height: 1.7;
  text-align: center;
  text-transform: uppercase;
}

/* ---------- Modal ---------- */

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: grid;
  place-items: center;
  padding: clamp(14px, 3vw, 34px);
  background: rgba(3, 6, 10, 0.74);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  opacity: 0;
  transition: opacity 0.22s var(--ease);
  overflow-y: auto;
}

.modal-backdrop.is-open {
  opacity: 1;
}

.modal {
  position: relative;
  width: min(520px, 100%);
  max-height: min(88vh, 880px);
  overflow-y: auto;
  padding: clamp(20px, 3vw, 30px);
  border-radius: 22px;
  border: 1px solid rgba(255, 180, 92, 0.18);
  background:
    linear-gradient(155deg, rgba(25, 39, 56, 0.95), rgba(8, 14, 23, 0.98) 58%),
    var(--panel-solid);
  box-shadow: 0 40px 110px rgba(0, 0, 0, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  transform: translateY(16px) scale(0.985);
  opacity: 0;
  transition: transform 0.28s var(--ease), opacity 0.28s var(--ease);
  scrollbar-width: thin;
  scrollbar-color: rgba(152, 194, 218, 0.2) transparent;
}

.modal-backdrop.is-open .modal {
  transform: none;
  opacity: 1;
}

.modal.is-wide {
  width: min(780px, 100%);
}

.modal-head {
  position: relative;
  padding-right: 38px;
}

.modal-head h2 {
  margin-top: 6px;
  font-family: var(--font-display);
  font-size: clamp(1.4rem, 3vw, 1.9rem);
  font-weight: 600;
  line-height: 1.16;
  color: #f4e9d6;
}

.modal-sub {
  margin-top: 8px;
  color: var(--muted);
  font-size: 0.8rem;
  line-height: 1.55;
}

.modal-close {
  position: absolute;
  top: -4px;
  right: -4px;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: rgba(8, 14, 23, 0.6);
  color: var(--muted);
  font-size: 1.1rem;
  line-height: 1;
  transition: color 0.2s, border-color 0.2s;
}

.modal-close:hover {
  color: var(--amber-soft);
  border-color: var(--line-warm);
}

.modal-content {
  margin-top: 18px;
}

.modal-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 22px;
}

.modal-actions .btn {
  flex: 1 1 150px;
  height: 44px;
  font-size: 0.73rem;
}

.modal-note {
  margin-top: 12px;
  color: var(--faint);
  font-size: 0.66rem;
  line-height: 1.5;
  text-align: center;
}

/* Result content */

.result-hero {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 18px;
  border-radius: 14px;
  border: 1px solid rgba(255, 180, 92, 0.2);
  background:
    radial-gradient(ellipse 70% 120% at 0% 0%, rgba(255, 160, 60, 0.14), transparent 70%),
    rgba(5, 10, 17, 0.5);
}

.result-score {
  font-family: var(--font-display);
  font-size: clamp(2.1rem, 5vw, 3rem);
  font-weight: 700;
  line-height: 1;
  color: var(--amber-soft);
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 34px rgba(255, 160, 60, 0.3);
}

.result-score small {
  margin-left: 6px;
  color: var(--faint);
  font-family: var(--font-body);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-shadow: none;
}

.result-rank {
  text-align: right;
  color: var(--muted);
  font-size: 0.67rem;
  line-height: 1.4;
}

.result-rank strong {
  display: block;
  color: var(--teal);
  font-family: var(--font-display);
  font-size: 1.2rem;
}

.breakdown {
  margin-top: 14px;
  display: grid;
  gap: 1px;
  border-radius: 12px;
  border: 1px solid var(--line-soft);
  overflow: hidden;
  background: var(--line-soft);
}

.breakdown-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 12px;
  background: rgba(7, 13, 21, 0.92);
  color: var(--muted);
  font-size: 0.71rem;
}

.breakdown-row span:last-child {
  color: #e9ddc9;
  font-family: var(--font-display);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.breakdown-row.is-total {
  background: rgba(255, 170, 70, 0.07);
  color: var(--amber-soft);
  font-weight: 700;
}

.breakdown-row.is-total span:last-child {
  color: var(--amber-soft);
  font-size: 0.9rem;
}

.breakdown-row.is-penalty span:last-child {
  color: #ff8b97;
}

.level-results {
  margin-top: 14px;
  display: grid;
  gap: 5px;
}

.level-result {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  padding: 7px 10px;
  border-radius: 9px;
  border: 1px solid var(--line-soft);
  background: rgba(7, 13, 21, 0.55);
  font-size: 0.69rem;
}

.level-result-index {
  color: var(--faint);
  font-family: var(--font-display);
  font-size: 0.65rem;
}

.level-result-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #c9d6dc;
}

.level-result-score {
  color: var(--amber-soft);
  font-family: var(--font-display);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.level-result.is-pending {
  opacity: 0.5;
}

/* Campaign level grid */

.level-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin-top: 16px;
}

.level-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
  min-height: 76px;
  padding: 10px 11px;
  border-radius: 11px;
  border: 1px solid var(--line);
  background: rgba(8, 14, 23, 0.66);
  text-align: left;
  transition: border-color 0.2s, background 0.2s, transform 0.2s;
}

.level-card:hover:not(:disabled) {
  border-color: rgba(255, 180, 92, 0.36);
  background: rgba(255, 170, 70, 0.06);
  transform: translateY(-1px);
}

.level-card.is-current {
  border-color: rgba(103, 243, 222, 0.36);
  background: rgba(103, 243, 222, 0.055);
}

.level-card.is-complete::after {
  content: '✓';
  position: absolute;
  top: 8px;
  right: 9px;
  color: var(--teal);
  font-size: 0.7rem;
}

.level-card:disabled {
  opacity: 0.38;
}

.level-card-number {
  color: var(--faint);
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.level-card-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
  color: #e2ecef;
  font-size: 0.7rem;
  font-weight: 700;
}

.level-card-score {
  margin-top: auto;
  color: var(--amber-soft);
  font-family: var(--font-display);
  font-size: 0.66rem;
  font-variant-numeric: tabular-nums;
}

.level-card.is-locked .level-card-score {
  color: var(--faint);
}

.campaign-progress {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 14px;
  padding: 9px 12px;
  border-radius: 10px;
  border: 1px solid var(--line-soft);
  background: rgba(5, 10, 17, 0.42);
  color: var(--muted);
  font-size: 0.69rem;
}

.campaign-progress strong {
  color: var(--amber-soft);
}

.progress-track {
  flex: 1;
  height: 4px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
}

.progress-track span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--teal-dim), var(--teal));
  box-shadow: 0 0 10px rgba(103, 243, 222, 0.5);
}

/* Help */

.help-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: 16px;
}

.help-item {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 10px 11px;
  border-radius: 11px;
  border: 1px solid var(--line-soft);
  background: rgba(7, 13, 21, 0.55);
}

.help-icon {
  display: grid;
  place-items: center;
  width: 25px;
  height: 25px;
  flex: 0 0 auto;
  border-radius: 7px;
  border: 1px solid rgba(255, 180, 92, 0.2);
  background: rgba(255, 170, 70, 0.07);
  color: var(--amber-soft);
  font-size: 0.8rem;
  font-weight: 700;
}

.help-item h4 {
  color: #dfe9ec;
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.help-item p {
  margin-top: 2px;
  color: var(--faint);
  font-size: 0.64rem;
  line-height: 1.4;
}

.help-score {
  margin-top: 12px;
  padding: 11px 13px;
  border-radius: 11px;
  border: 1px solid rgba(255, 180, 92, 0.15);
  background: rgba(255, 170, 70, 0.045);
  color: var(--muted);
  font-size: 0.68rem;
  line-height: 1.55;
}

.help-score strong {
  color: var(--amber-soft);
}

/* Name form */

.name-form {
  display: grid;
  gap: 8px;
  margin-top: 16px;
}

.name-form label {
  color: var(--faint);
  font-size: 0.63rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.name-form input {
  width: 100%;
  height: 46px;
  padding: 0 14px;
  border-radius: 11px;
  border: 1px solid var(--line);
  background: rgba(4, 9, 15, 0.72);
  color: #f1e6d3;
  font-size: 0.95rem;
  letter-spacing: 0.02em;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.name-form input:focus {
  outline: none;
  border-color: rgba(255, 180, 92, 0.5);
  box-shadow: 0 0 0 3px rgba(255, 180, 92, 0.1);
}

.name-form .form-hint {
  color: var(--faint);
  font-size: 0.64rem;
}

.form-error {
  min-height: 1em;
  color: #ff8b97;
  font-size: 0.66rem;
}

/* ---------- Toasts ---------- */

.toast-root {
  position: fixed;
  right: max(16px, env(safe-area-inset-right));
  bottom: max(16px, env(safe-area-inset-bottom));
  z-index: 120;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
  pointer-events: none;
  width: min(360px, calc(100vw - 32px));
}

.toast {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  width: 100%;
  padding: 11px 13px;
  border-radius: 11px;
  border: 1px solid var(--line);
  border-left: 3px solid var(--amber);
  background: rgba(10, 17, 27, 0.94);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.5);
  color: #dbe6ea;
  font-size: 0.72rem;
  line-height: 1.4;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  transform: translateX(14px);
  opacity: 0;
  animation: toast-in 0.3s var(--ease) forwards;
  pointer-events: auto;
}

.toast.is-leaving {
  animation: toast-out 0.25s var(--ease) forwards;
}

.toast-icon {
  flex: 0 0 auto;
  color: var(--amber);
  font-size: 0.8rem;
  line-height: 1.3;
}

.toast.is-success {
  border-left-color: var(--teal);
}

.toast.is-success .toast-icon {
  color: var(--teal);
}

.toast.is-warn {
  border-left-color: var(--red);
}

.toast.is-warn .toast-icon {
  color: var(--red);
}

.toast.is-season {
  border-left-color: var(--violet);
}

.toast.is-season .toast-icon {
  color: var(--violet);
}

@keyframes toast-in {
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes toast-out {
  to {
    opacity: 0;
    transform: translateX(14px);
  }
}

