import { Game, countBits } from './game.mjs'
import { BoardRenderer } from './renderer.mjs'
import { Leaderboard } from './leaderboard.mjs'
import { AudioEngine } from './audio.mjs'
import { getWeekInfo, getWeeklyLevels, formatCountdown } from './season.mjs'
import { CAMPAIGN_LEVELS } from './data/campaign.mjs'
import {
  loadCampaign,
  saveCampaign,
  loadSettings,
  saveSettings,
  sanitizeName,
} from './storage.mjs'

const $ = (id) => document.getElementById(id)

const TIPS = [
  'Buz üzerinde tek bir hamle seni birkaç kare kaydırabilir. Duvarları hesaba kat.',
  'Nöbetçiler her turda hareket eder; bekleme de bir tur harcar.',
  'Çatlak taşlar arkanda çöker. Geri dönüş yolunu kapatmamaya çalış.',
