import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })
for (const mode of ['setTimeout0','setTimeout300','evaluate','blurfocus','none']) {
 const page = await browser.newPage({ viewport:{width:1440,height:900} })
 await page.goto('http://localhost:3002/', {waitUntil:'load'})
 if(mode==='setTimeout0') await page.evaluate(()=>setTimeout(()=>window.focus(),0))
 if(mode==='setTimeout300') await page.evaluate(()=>setTimeout(()=>window.focus(),300))
 if(mode==='evaluate') await page.evaluate(()=>window.focus())
 if(mode==='blurfocus') await page.evaluate(()=>{window.blur();window.focus()})
 await page.waitForTimeout(400)
 const vis = await page.evaluate(()=>({state:document.visibilityState,focus:document.hasFocus()}))
 try { await page.locator('#intro-weekly').click({trial:true,timeout:1500}); console.log(mode,'ok',vis) } catch(e) { console.log(mode,'fail',vis) }
 await page.close()
}
await browser.close()
